#!/usr/bin/env bash
set -euo pipefail

state_file="${XDG_CONFIG_HOME:-$HOME/.config}/caelestia/plugin-settings.json"
lua_file="${XDG_CONFIG_HOME:-$HOME/.config}/caelestia/plugin-settings.lua"

generate() {
    local tmp
    tmp=$(mktemp "${lua_file}.XXXXXX")
    jq -r '
        .["dynamic-cursors"] as $d |
        "-- Generated by Nexus > Plugins. Advanced settings can remain in hypr-user.lua.\n" +
        "if hl.plugin.dynamic_cursors then\n" +
        "    hl.config { plugin = { dynamic_cursors = {\n" +
        "        mode = " + ($d.mode | tojson) + ",\n" +
        "        threshold = " + ($d.threshold | tostring) + ",\n" +
        "        shake = { enabled = " + ($d.shakeEnabled | tostring) + " },\n" +
        "    }}}\n" +
        "end\n"
    ' "$state_file" > "$tmp"
    mv "$tmp" "$lua_file"
}

case "${1:-list}" in
    list)
        jq -r '.["dynamic-cursors"] | [.mode, .threshold, .shakeEnabled] | @tsv' "$state_file"
        ;;
    set)
        key=${2:-}
        value=${3:-}
        tmp=$(mktemp "${state_file}.XXXXXX")
        case "$key" in
            mode)
                [[ "$value" =~ ^(tilt|rotate|stretch|none)$ ]]
                jq --arg value "$value" '.["dynamic-cursors"].mode = $value' "$state_file" > "$tmp"
                ;;
            threshold)
                [[ "$value" =~ ^[0-9]+([.][0-9]+)?$ ]]
                jq --argjson value "$value" '.["dynamic-cursors"].threshold = $value' "$state_file" > "$tmp"
                ;;
            shakeEnabled)
                [[ "$value" == true || "$value" == false ]]
                jq --argjson value "$value" '.["dynamic-cursors"].shakeEnabled = $value' "$state_file" > "$tmp"
                ;;
            *)
                rm -f -- "$tmp"
                printf 'Unknown setting: %s\n' "$key" >&2
                exit 2
                ;;
        esac
        mv "$tmp" "$state_file"
        generate
        hyprctl reload >/dev/null
        ;;
    generate)
        generate
        ;;
    *)
        printf 'usage: %s {list|set KEY VALUE|generate}\n' "$0" >&2
        exit 2
        ;;
esac
